with exploded as (select id, service, host, latency_ms, status_code, attr_key, value from app_logs lateral view explode(context) e as attr_key, value) select id, service, status_code, attr_key, value, round(status_code / sum(status_code) over (partition by service), 4) as status_code_share, corr(status_code, latency_ms) over (partition by host) as corr_status_code_latency_ms, cume_dist() over (partition by service order by latency_ms desc nulls first) as latency_ms_cume_dist from exploded
